#!/data/data/com.termux/files/usr/bin/bash
# 高校认证 Termux 一键安装（加密载荷 + 字节码壳，无明文源码）
set -e
pkg install -y nodejs-lts
npm install -g bytenode
mkdir -p ~/chsi && cd ~/chsi
echo '' | base64 -d > app-enc.json
echo '' | base64 -d > core.js
npm install bytenode
node -e "require('bytenode').compileFile({filename:'core.js',output:'core.jsc'})"
rm -f core.js
cat > run.sh <<'EOF2'
#!/data/data/com.termux/files/usr/bin/bash
cd ~/chsi && exec node -e "require('bytenode');require('./core.jsc')" 2>&1
EOF2
chmod +x run.sh
echo 安装完成。启动: ~/chsi/run.sh ，浏览器开 http://127.0.0.1:8901 设置
